def binary_search(xs, target):
    left, right = 0, len(xs) - 1
    while left <= right:
        mid = (left + right) // 2
        if xs[mid] == target:
            return mid
        elif xs[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def merge_sorted(a, b):
    merged = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1
    merged.extend(a[i:])
    merged.extend(b[j:])
    return merged

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.isqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def longest_common_prefix(strings):
    if not strings:
        return ""
    prefix = strings[0]
    for s in strings[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def parse_key_value_lines(text: str) -> Dict[str, str]:
    pattern = re.compile(r'^\s*([^=\s]+)\s*=\s*(.*?)\s*$', re.MULTILINE)
    return {match.group(1): match.group(2) for match in pattern.finditer(text)}

def moving_average(xs, window):
    if window <= 0 or window > len(xs):
        return []
    return [sum(xs[i:i+window]) / window for i in range(len(xs) - window + 1)]

def group_by_first_letter(words):
    grouped = defaultdict(list)
    for word in words:
        first_letter = word[0] if word else ''
        grouped[first_letter].append(word)
    return dict(grouped)
